import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";

import { users } from "./auth";

/** A table-of-contents entry, resolved to a 1-based page number at upload. */
export type BookOutlineItem = {
  title: string;
  /** null when the destination couldn't be resolved to a page. */
  page: number | null;
  items: BookOutlineItem[];
};

export const books = pgTable(
  "books",
  {
    // Generated by the server when presigning, so it's part of the R2 keys.
    id: uuid().primaryKey(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    title: text().notNull(),
    author: text(),
    fileKey: text().notNull(),
    coverKey: text(),
    pageCount: integer().notNull(),
    fileSize: bigint({ mode: "number" }).notNull(),
    hasTextLayer: boolean().notNull(),
    outline: jsonb().$type<BookOutlineItem[]>(),
    createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("books_file_key_unique").on(t.fileKey),
    index("books_user_id_created_at_idx").on(
      t.userId,
      sql`${t.createdAt} desc`,
    ),
  ],
);
